// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));
        address oldOwner = c.owner();
        vm.prank(caller);
        c.transferOwnership(newOwner);
        if (caller == oldOwner) {
            assertEq(c.owner(), newOwner);
        } else {
            assertEq(c.owner(), oldOwner);
        }
    }
}
